import { HealthService } from '../../services/health.service.js';
import { navigate } from '../../router.js';
import { withActivityStart } from './health-utils.js';
import type { Activity } from '@motivation/shared';

/**
 * Create a manual activity and open the Activity Detail Hub for it (story 181).
 *
 * Replaces the old per-screen "create, then branch on `weight_training` →
 * strength screen, else stay" logic that the dashboard and day screen each had a
 * copy of. Now every new activity lands on the hub (story 179), where the user
 * attaches a cardio and/or workout component — or neither. One flow for runs,
 * lifts, both-at-once HIT sessions, and bare entries.
 */
export async function createActivityAndOpenHub(data: {
    title: string;
    type: string;
    date: string;
    duration_minutes?: number;
    /**
     * Optional `HH:MM` local start (story 299). Stored as an instant in `metadata.start`, which is
     * what lets the Health Connect write-back publish the session at the time it happened instead
     * of at a placeholder.
     */
    start_time?: string;
}): Promise<Activity> {
    const { start_time, ...fields } = data;
    const activity = await HealthService.createActivity(
        start_time ? { ...fields, metadata: withActivityStart(null, data.date, start_time) } : fields,
    );
    navigate(`/health/activity/${encodeURIComponent(activity.id)}`);
    return activity;
}

/**
 * Adopt a Google Calendar class into a stored row and open the hub on it (story 323).
 *
 * The same shape as {@link createActivityAndOpenHub} and for the same reason — a class the owner
 * has just confirmed attending is one they usually want to add a distance or an exercise list to,
 * and the hub is where that happens. Tapping and going no further is still complete: the row is
 * stored before this navigates.
 */
export async function adoptCalendarActivityAndOpenHub(event: Activity): Promise<Activity> {
    const activity = await HealthService.adoptCalendarActivity(event);
    navigate(`/health/activity/${encodeURIComponent(activity.id)}`);
    return activity;
}
